fog = mix( fog, 1.0, depth*depth*clamp01(fog*2.0) );//push the beam to white at max distance
vec2 shadowUV = (uv-0.5) * pow(min(depth*4.0,1.0),1.09) + 0.5;
float shadow = texture( sampler_main, shadowUV ).g; float rim = clamp01( shadow * 3.0 - 2.0 );
float interSect = smoothstep( 0.24, 0.26, depth ); interSect *= (1.0-interSect) * 14.0 * (rim)*(1.0-rim);
interSect *= clamp01(fog*8.0);
float toSoft = clamp01( depth * 8.0 - 2.0 ); shadow = clamp01( shadow.xxx * (toSoft*9.0+1.0) - toSoft*9.0 );
fog *= 1.0 - shadow;
fog += interSect;
vec3 weCanHazLasers = fog;
weCanHazLasers = pow( weCanHazLasers, Col );
ret = 0;// weCanHazLasers;
ret += ( warpShaderOut.r * HexCol ) * clamp01(1.0-fog*2.0);
//zw of botcoords is can coords
//note: uAspect.y is 1.0/uAspectY from per uFrame - widescreen is < 1.0
vec2 uvS = vec2( uv.x, uv.y - VertShift) * uAspect.xy;
uvS.y = uvS.y;
vec2 graffCoords = uvS * 1.8 * vec2( 1.0, 4.0 * 256.0/275.0 ) + vec2( -0.6, -1.2 );
graffCoords.xy = (graffCoords.xy-vec2(0.25,0.5))*GraffScale+vec2(0.25,0.5);
graffCoords.xy += dot( warpShaderOut.rb, vec2(2.0,1.0) ) * q23 * 0.15;
vec2 graffMask2 = abs( graffCoords - 0.5 ) < 0.5;
float graffMask = min( graffMask2.x, graffMask2.y );
vec4 graff = 0.5;
vec2 graffSwipe = smoothstep( Swipe.xy, Swipe.zw, graffCoords.xx );// smoothstep( 1.0-Swipe*1.3, 1.0-(Swipe*1.3-0.3), graffCoords.xx ) ;
if( graffMask > 0.5 )
{
graffCoords.y = graffCoords.y * 0.25 + floor(q20) * 0.25;
graff = textureLod4( sampler_graffBotGraff00, vec4(graffCoords,0.0, (1.0-graffSwipe.y)*5.0 + q23*5.0 ) );
graff.rgb *= clamp01( graff.b - graff.r ) * Vol * 1.0 + 1.0;
}
graff.a *= graffMask;
graff = mix( vec4( 0.5,0.5,0.5,0.0 ), graff, graffSwipe.x * (1.0-q23) );
vec4 botCoords = uvS.xyxy /* uAspect.xyxy*/ * vec4( 0.6, 0.6, CanStart.xy ) - vec4( 0.35, 0.08, CanStart.zw );
//foo = vec4( fract(botCoords.xyx) + vec3(0.0,0.0,botCoords.y > 1.0), 1.0 );
//foo = vec4( botCoords.xyx, 1.0 );
vec2 botCoordsStart = botCoords; botCoords.xy +=  - vec4( AnimMove, 0.0, 0.0 );
botCoords.zw = mix( botCoords.zw, (botCoordsStart-vec2(0.18,0.25))*CanStart.xy+vec2(0.27,0.25), CanAnimTime );
botCoords.zw = mix( botCoords.zw, botCoordsStart, CanGrowTime );
botCoords.zw = multiply( botCoords.zw-1.0/8.0, CanRotMat ) + 1.0/8.0;
botCoords.xy += dot( warpShaderOut.rb, vec2(2.0,1.0)) * BotExitTime * 0.05;
vec4 botMask2 = abs( botCoords * 4.0 - 0.5 ) < 0.5;
vec2 botMask = botMask2.xz * botMask2.yw;
//foo = vec4( botCoords.x, dot(botMask, vec3(0.5)), botCoords.y, 1.0 );
vec4 bot = 0;
vec4 can = 0;
if( botMask.x > 0.5 )
{
bot = textureBias( sampler_graffBotAnim01, vec4( botCoords.xy + AnimOffset, 0.0, -2.0 ) );
bot = dot( bot, AnimChannel );
bot -= BotExitTime*BotExitTime;
}
if( botMask.y > 0.5 )
{
can = texture( sampler_graffBotAnim01, botCoords.zw );
}
bot = smoothstep( vec4( 0.2, 0.25, 0.7, 0.85 ), vec4( 0.3, 0.55, 0.8, 1.0 ), bot.r );
bot = vec4( dot( bot.gb, 1.0/4.0 ).xxx + bot.a*weCanHazLasers, bot.x );
bot.a *= 1.0 - BotExitTime;
can = smoothstep( vec4( 0.2, 0.25, 0.7, 0.85 ), vec4( 0.3, 0.55, 0.8, 1.0 ), can.r );
can = vec4( dot( can.gb, 1.0/4.0 ).xxx + can.a*weCanHazLasers, can.x );
//bot.rgb *= mix( 1.0, bot.rgb, vec3(1.0,0.5,0.0) );
//composite graff
ret = mix( mix(ret, ret * graff * 2.0, graff.a), graff, graff.a * 0.75 );
//composite bot and can
ret = mix( ret, can, can.a );
ret = mix( ret, bot, bot.a );
ret += weCanHazLasers;
/*
vec2 uvFlare = ( uv - 0.5 ) * uAspect;
uvFlare = atan( (uvFlare.x) / (uvFlare.y) ) * 6.0;
uvFlare = abs( fract(uvFlare) * 2.0 - 1.0 );
uvFlare = (uv-0.5)*uvFlare+0.5;
vec3 flare = texture( sampler_pw_main, uvFlare );
ret = flare;
*/
//ret = fract(topCoords.xz * vec2(1.0,16.0)).xyx;
//ret = topScan / 4.0;
//ret = GetPixel(uv);
ret = foo.w > 0.5 ? foo.rgb : ret;
//ret = warpShaderOut.rgb;
}
  fragColor = vec4(ret, 1.0);
}

