static const float CanGrowTime = smoothstep( 0.0, 1.0, q26 );
static const float BotExitTime = q27;
static const float2 BeamPan = lerp( float2( 37.5 + ( frac( (sin(time*1.0)*0.5+0.5)*8.0 ) * 30.0 - 15.0 ) * saturate(1.0-frac(time*0.11)*4.0)
+ pow( saturate( frac(time*0.11) * 5.0 ), 2.0 ) * float2( -20.0, 20.0 )  ),
