botCoords.zw = mul( botCoords.zw-1.0/8.0, CanRotMat ) + 1.0/8.0;
botCoords.xy += dot( warpShaderOut.rb, float2(2.0,1.0)) * BotExitTime * 0.05;
float4 botMask2 = abs( botCoords * 4.0 - 0.5 ) < 0.5;
float2 botMask = botMask2.xz * botMask2.yw;
//foo = float4( botCoords.x, dot( botMask, 0.5 ), botCoords.y, 1.0 );
float4 bot = 0;
float4 can = 0;
if( botMask.x > 0.5 )
{
bot = tex2Dbias( sampler_graffBotAnim01, float4( botCoords.xy + AnimOffset, 0.0, -2.0 ) );
bot = dot( bot, AnimChannel );
bot -= BotExitTime*BotExitTime;
}
if( botMask.y > 0.5 )
{
can = tex2D( sampler_graffBotAnim01, botCoords.zw );
}
bot = smoothstep( float4( 0.2, 0.25, 0.7, 0.85 ), float4( 0.3, 0.55, 0.8, 1.0 ), bot.r );
bot = float4( dot( bot.gb, 1.0/4.0 ).xxx + bot.a*weCanHazLasers, bot.x );
bot.a *= 1.0 - BotExitTime;
can = smoothstep( float4( 0.2, 0.25, 0.7, 0.85 ), float4( 0.3, 0.55, 0.8, 1.0 ), can.r );
can = float4( dot( can.gb, 1.0/4.0 ).xxx + can.a*weCanHazLasers, can.x );
//bot.rgb *= lerp( 1.0, bot.rgb, float3(1.0,0.5,0.0) );
//composite graff
ret = lerp( lerp(ret, ret * graff * 2.0, graff.a), graff, graff.a * 0.75 );
//composite bot and can
ret = lerp( ret, can, can.a );
ret = lerp( ret, bot, bot.a );
ret += weCanHazLasers;
/*
float2 uvFlare = ( uv - 0.5 ) * aspect;
uvFlare = atan( (uvFlare.x) / (uvFlare.y) ) * 6.0;
uvFlare = abs( frac(uvFlare) * 2.0 - 1.0 );
uvFlare = (uv-0.5)*uvFlare+0.5;
float3 flare = tex2D( sampler_pw_main, uvFlare );
ret = flare;
*/
//ret = frac(topCoords.xz * float2(1.0,16.0)).xyx;
//ret = topScan / 4.0;
//ret = GetPixel(uv);
ret = foo.w > 0.5 ? foo.rgb : ret;
//ret = warpShaderOut.rgb;
}

normalized.dialectSource:
/*2010 Anandamide Logistics
Anandamide is Phat and Eo.S.
Concept by Phat
Graffiti font created in Context Free by ForceField
Spraypaint can concept by Phat
Spraypaint can 3d modeling created in 3d Studio Max by Eo.S.
Graffiti created by Phat with character and graffiti illustrations from Phat Eo.S. and ForceField
Graffiti created in Structure Synth by Phat
Milkdrop code created by Eo.S.
Special thanks to Phong who masked out the electromagnetic spectrum used in the graffiti
If your going to remix this please do it right.*/
sampler sampler_graffBotAnim01;
sampler sampler_graffBotGraff00;
const float AnimTime = fract( q20 );//is + 1.0 for 2nd graff tex
const vec2 AnimOffset = vec2( floor( fract( fract(q20) * 4.0 ) * 4.0 ) / 4.0, floor( fract(q20) * 4.0 ) / 4.0 );
const vec4 AnimChannel = (fract( fract(q20) * 16.0 ) >= vec4( 0.0, 0.25, 0.5, 0.75 )) * (fract( fract(q20) * 16.0 ) < vec4( 0.25, 0.5, 0.75, 1.0 ));
const vec2 GraffScale = vec2( 1.0 - q17*0.01, 1.0 - q17*0.01 );
const float Vol = pow( (audioLow+audioMid+audioHigh)*0.25, 2.0 );
const vec2 AnimMove = vec2( q21 * -0.35, 0.0 );
const vec4 Swipe = vec4( 1.0-q21*1.3, 1.0-q22*1.3, 1.0-(q21*1.3-0.3), 1.0-(q22*1.3-0.3) );
const float VertShift = (1.31-pow( (1.0/uAspect.y - 1.0)*1.19+1.0, 0.5 )) * 1.03 + 0.115;
const mat4 MatViewI = mat4( q1, q2, q3, q4,  q5, q6, q7, q8,  q9, q10, q11, q12,  q13, q14, q15, q16 );
const vec3 ViewPos = vec3( q4, q8, q12 );//vec3( q17, q18, q19 );
const float BeamTop = 0.4;//sin( uTime * 0.4 ) * 30.0;
const float BeamBtm = BeamTop - 0.8;
const float BeamDensity = 1.0 / 15.0;
const vec2 ScanMod = vec2( sin( q24 * 1.1 ) * 0.2 + 0.2, sin( q24 * 0.5 ) * 14.0 + 4.0 );
//const vec2 BeamCurveBase = pow( smoothstep( -1.0, 1.0, vec2( sin( q24 / 1.0 ), sin( uTime / 2.3 ) * 1.5 - 0.5 ) ), 2.0 ) * 1.0;
const vec2 BeamCurve = q31;//(sqrt(smoothstep(0.0,0.5,BeamCurveBase)) + pow(smoothstep(0.5,1.0,BeamCurveBase),2.0)*0.6)/2.0;
const vec2 StripeBounds = ( sin( uTime.xx / 1.1 ) * abs(sin(uTime.xx/1.1)) * 0.5 + 0.5 ) * 0.93 + vec2( 0.0, 0.07 );
const vec3 Col = mix( vec3( 4.0, 1.0, 1.2 ),
mix( vec3( 4.0, 1.5, 1.0 ), vec3( 6.0, 1.0, 0.5 ), smoothstep( 0.5, 1.5, audioMid ) ),
q18 );
const vec3 HexCol = mix( vec3( 0.0, 1.0, 1.0 ), vec3( 0.0, 0.5, 1.0 ), q18 );
const float CanAnimTime = pow(q25,0.5);
const vec4 CanStart = vec4( 1.0, 1.0, 0.27, 0.2 - (pow(q25,2.0)*(1.0-pow(q25,0.5)))*3.0 ) * 3.0 + //tiling, offset
vec4( 0.0, 0.0, (q25 == 0 ? (1.0-q21) * 1.75 : 0.0)+0.02, 0.03 ) + //this line moves the can to stay in bot's hand during spray
vec4( 0.0, 0.0,  fract(q20) < 0.9374 ? 100.0 : 0.0, 0.0 );//remove can during transform by pushing off screen
//it seems in some cases, that basing preshader variables on other preshader variables causes them to instead be calculated in the
//shader. But not always...
const mat2 CanRotMat = mat2( cos(sqrt(q25)*12.57), -sin(sqrt(q25)*12.57), sin(sqrt(q25)*12.57), cos(sqrt(q25)*12.57) );
const float CanGrowTime = smoothstep( 0.0, 1.0, q26 );
const float BotExitTime = q27;
const vec2 BeamPan = mix( vec2( 37.5 + ( fract( (sin(uTime*1.0)*0.5+0.5)*8.0 ) * 30.0 - 15.0 ) * clamp01(1.0-fract(uTime*0.11)*4.0)
+ pow( clamp01( fract(uTime*0.11) * 5.0 ), 2.0 ) * vec2( -20.0, 20.0 )  ),
vec2(-10000.0,10000.0), 1.0 - clamp01( q30 / 0.004 ) );
shader_body {//SHADER BODY---------------
vec4 foo = 0;//if w is 1, output is overridden with foo
vec3 warpShaderOut = GetPixel(uv);
ret = texture( sampler_main, uv_orig ).xyz;
vec4 position_vs = vec4( (uv.xy * vec2(2.0,2.0) + vec2(-1.0,-1.0)) * uAspect * 100.0, 0.0, 1.0 );
position_vs.xy = mix( position_vs.xy, length( position_vs.xy ), BeamCurve.x );
vec4 position_ws = multiply( position_vs, MatViewI );
//vec3 ground_ws = vec3( (uv.xy * 2.0 - 1.0 ) * uAspect, (1.0-clamp01(uv.y) * 100.0 + 1.0 ) );
//ground_ws.xy *= ground_ws.z;
//vec3 foo = fract(ground_ws / 1.0 );
vec3 viewVec = position_ws.xyz - ViewPos;//vector from camera to world position
float top = BeamTop;
float btm = BeamBtm;
if( viewVec.y > 0.0 )//if angled up
{
//top of section must be below vector end, and above vector start
top = min( top, position_ws.y );
top = max( top, ViewPos.y );
btm = min( btm, position_ws.y );
btm = max( btm, ViewPos.y );
}
else //angled down
{
//top of section must be below vector start, and above vector end
top = min( top, ViewPos.y );
top = max( top, position_ws.y );
btm = min( btm, ViewPos.y );
btm = max( btm, position_ws.y );
}
float section = top - btm;
float sectionAmount = ( abs(section) / abs(viewVec.y) );
float distToTop = abs(ViewPos.y - (ViewPos.y>BeamBtm?BeamTop:BeamBtm)) / abs(viewVec.y); //distToTop *= length( viewVec );
vec3 topCoords = ViewPos + distToTop * viewVec;
float angle = atan( -topCoords.z, topCoords.x ); float depth = clamp01( 1.0 - (topCoords.z / -100.0) ); float modPinWidth = depth*depth*0.15;//widens the thin beams in the distance
topCoords.xz = topCoords.xz / 4.0;
topCoords.xz = (topCoords.xz + vec2( 0.0, 25.0 - abs(q30/0.15) * 5.0 )) / (abs(q30)*10.0+1.0);//adjust tiling so it doesn't move so much
topCoords.xz *= 2.0;//extra tiling adjustment
float stripeBase = clamp( angle * 24.0, BeamPan.x, BeamPan.y ); float beamLimit = clamp01( (stripeBase-BeamPan.x) / (BeamPan.y-BeamPan.x) );
vec2 beamLimit2 = smoothstep( vec2(0.0,0.0), vec2(0.03,0.2), beamLimit * (1.0 - beamLimit) );
beamLimit = beamLimit2.x + beamLimit2.x * (1.0-beamLimit2.x) * 10.0;
float topScan = fract( stripeBase * ScanMod.x + ScanMod.y );
float stripe = smoothstep( StripeBounds.x - modPinWidth, StripeBounds.y + modPinWidth, abs( topScan * 2.0 - 1.0 ) );//bounds have a separation of 0.07 - beam stripes
float phaseBase = fract( stripeBase * 0.01 + uTime * 16.0 ); float phase = smoothstep( 0.31, 1.0, phaseBase * (1.0-phaseBase) * 4.0 );
topScan = stripe + (1.0-abs(stripe*2.0-1.0))*14.0 + 0.3;//strip + thin beams at stripe edges
topScan *= phase;
float smoke = GetPixel( (topCoords.xz / 4.0) / (abs(q30)*24.0 + 1.0) + vec2( q32, 0.0 ) ).b;
topScan *= smoke*smoke * 4.0 + 0.5;
float fogDepth = sectionAmount * length( viewVec );
float fog = 1.0 - 1.0 / (fogDepth * BeamDensity * (topScan + 0.8 ) + 1.0);
fog *= beamLimit.x;
fog = mix( fog, 1.0, depth*depth*clamp01(fog*2.0) );//push the beam to white at max distance
vec2 shadowUV = (uv-0.5) * pow(min(depth*4.0,1.0),1.09) + 0.5;
float shadow = texture( sampler_main, shadowUV ).g; float rim = clamp01( shadow * 3.0 - 2.0 );
float interSect = smoothstep( 0.24, 0.26, depth ); interSect *= (1.0-interSect) * 14.0 * (rim)*(1.0-rim);
interSect *= clamp01(fog*8.0);
float toSoft = clamp01( depth * 8.0 - 2.0 ); shadow = clamp01( shadow.xxx * (toSoft*9.0+1.0) - toSoft*9.0 );
fog *= 1.0 - shadow;
fog += interSect;
vec3 weCanHazLasers = fog;
weCanHazLasers = pow( weCanHazLasers, Col );
ret = 0;// weCanHazLasers;
ret += ( warpShaderOut.r * HexCol ) * clamp01(1.0-fog*2.0);
//zw of botcoords is can coords
//note: uAspect.y is 1.0/uAspectY from per uFrame - widescreen is < 1.0
vec2 uvS = vec2( uv.x, uv.y - VertShift) * uAspect.xy;
uvS.y = uvS.y;
vec2 graffCoords = uvS * 1.8 * vec2( 1.0, 4.0 * 256.0/275.0 ) + vec2( -0.6, -1.2 );
graffCoords.xy = (graffCoords.xy-vec2(0.25,0.5))*GraffScale+vec2(0.25,0.5);
graffCoords.xy += dot( warpShaderOut.rb, vec2(2.0,1.0) ) * q23 * 0.15;
vec2 graffMask2 = abs( graffCoords - 0.5 ) < 0.5;
float graffMask = min( graffMask2.x, graffMask2.y );
vec4 graff = 0.5;
vec2 graffSwipe = smoothstep( Swipe.xy, Swipe.zw, graffCoords.xx );// smoothstep( 1.0-Swipe*1.3, 1.0-(Swipe*1.3-0.3), graffCoords.xx ) ;
if( graffMask > 0.5 )
{
graffCoords.y = graffCoords.y * 0.25 + floor(q20) * 0.25;
graff = textureLod4( sampler_graffBotGraff00, vec4(graffCoords,0.0, (1.0-graffSwipe.y)*5.0 + q23*5.0 ) );
graff.rgb *= clamp01( graff.b - graff.r ) * Vol * 1.0 + 1.0;
}
graff.a *= graffMask;
graff = mix( vec4( 0.5,0.5,0.5,0.0 ), graff, graffSwipe.x * (1.0-q23) );
vec4 botCoords = uvS.xyxy /* uAspect.xyxy*/ * vec4( 0.6, 0.6, CanStart.xy ) - vec4( 0.35, 0.08, CanStart.zw );
//foo = vec4( fract(botCoords.xyx) + vec3(0.0,0.0,botCoords.y > 1.0), 1.0 );
//foo = vec4( botCoords.xyx, 1.0 );
vec2 botCoordsStart = botCoords; botCoords.xy +=  - vec4( AnimMove, 0.0, 0.0 );
botCoords.zw = mix( botCoords.zw, (botCoordsStart-vec2(0.18,0.25))*CanStart.xy+vec2(0.27,0.25), CanAnimTime );
botCoords.zw = mix( botCoords.zw, botCoordsStart, CanGrowTime );
botCoords.zw = multiply( botCoords.zw-1.0/8.0, CanRotMat ) + 1.0/8.0;
botCoords.xy += dot( warpShaderOut.rb, vec2(2.0,1.0)) * BotExitTime * 0.05;
vec4 botMask2 = abs( botCoords * 4.0 - 0.5 ) < 0.5;
vec2 botMask = botMask2.xz * botMask2.yw;
//foo = vec4( botCoords.x, dot(botMask, vec3(0.5)), botCoords.y, 1.0 );
vec4 bot = 0;
vec4 can = 0;
if( botMask.x > 0.5 )
{
bot = textureBias( sampler_graffBotAnim01, vec4( botCoords.xy + AnimOffset, 0.0, -2.0 ) );
bot = dot( bot, AnimChannel );
bot -= BotExitTime*BotExitTime;
}
if( botMask.y > 0.5 )
{
can = texture( sampler_graffBotAnim01, botCoords.zw );
}
bot = smoothstep( vec4( 0.2, 0.25, 0.7, 0.85 ), vec4( 0.3, 0.55, 0.8, 1.0 ), bot.r );
bot = vec4( dot( bot.gb, 1.0/4.0 ).xxx + bot.a*weCanHazLasers, bot.x );
bot.a *= 1.0 - BotExitTime;
can = smoothstep( vec4( 0.2, 0.25, 0.7, 0.85 ), vec4( 0.3, 0.55, 0.8, 1.0 ), can.r );
can = vec4( dot( can.gb, 1.0/4.0 ).xxx + can.a*weCanHazLasers, can.x );
//bot.rgb *= mix( 1.0, bot.rgb, vec3(1.0,0.5,0.0) );
//composite graff
ret = mix( mix(ret, ret * graff * 2.0, graff.a), graff, graff.a * 0.75 );
//composite bot and can
ret = mix( ret, can, can.a );
ret = mix( ret, bot, bot.a );
ret += weCanHazLasers;
/*
vec2 uvFlare = ( uv - 0.5 ) * uAspect;
uvFlare = atan( (uvFlare.x) / (uvFlare.y) ) * 6.0;
uvFlare = abs( fract(uvFlare) * 2.0 - 1.0 );
uvFlare = (uv-0.5)*uvFlare+0.5;
vec3 flare = texture( sampler_pw_main, uvFlare );
ret = flare;
*/
//ret = fract(topCoords.xz * vec2(1.0,16.0)).xyx;
//ret = topScan / 4.0;
//ret = GetPixel(uv);
ret = foo.w > 0.5 ? foo.rgb : ret;
//ret = warpShaderOut.rgb;
}
